CREATE TABLE IF NOT EXISTS article_behavior_stat (article_id BIGINT NOT NULL, like_count BIGINT NOT NULL DEFAULT 0, view_count BIGINT NOT NULL DEFAULT 0, comment_count BIGINT NOT NULL DEFAULT 0, collect_count BIGINT NOT NULL DEFAULT 0, updated_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (article_id), CONSTRAINT chk_behavior_counts CHECK (like_count >= 0 AND view_count >= 0 AND comment_count >= 0 AND collect_count >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS article_like (id BIGINT NOT NULL AUTO_INCREMENT, article_id BIGINT NOT NULL, user_id BIGINT NOT NULL, status TINYINT NOT NULL DEFAULT 1, created_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uk_article_user (article_id, user_id), KEY idx_user_status (user_id, status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS behavior_event_log (id BIGINT NOT NULL AUTO_INCREMENT, event_id VARCHAR(64) NOT NULL, article_id BIGINT NOT NULL, user_id BIGINT NULL, behavior_type VARCHAR(24) NOT NULL, delta_value INT NOT NULL, occurred_at DATETIME(3) NOT NULL, processed_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uk_event_id (event_id), KEY idx_article_processed (article_id, processed_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS behavior_failed_event (id BIGINT NOT NULL AUTO_INCREMENT, event_id VARCHAR(64) NULL, article_id BIGINT NULL, payload TEXT NOT NULL, error_message VARCHAR(500) NOT NULL, failed_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), KEY idx_event_id (event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
